+import { $internal } from '../common';
+import type { Entity } from '../entity/types';
+import { getEntityId } from '../entity/utils/pack-entity';
+import { isRelation } from '../relation/utils/is-relation';
+import { getTrait, hasTrait } from '../trait/trait';
+import type { Trait } from '../trait/types';
+import type { World } from '../world';
+import { createModifier } from './modifier';
+import { checkQueryWithRelations } from './utils/check-query-with-relations';
+import type { Modifier, PredicateModifier, QueryInstance } from './types';
+
+let predicateId = 0;
+
+/** Creates a value-based entity filter. Predicate dependencies must be data traits. */
+export function createPredicate<T extends Trait[]>(
+    traits: T,
+    predicate: (values: { [K in keyof T]: ReturnType<T[K][typeof $internal]['get']> }) => boolean
+): PredicateModifier<T> {
+    for (const trait of traits) {
+        if (trait[$internal].type === 'tag') {
+            throw new Error('Koota: Tags cannot be predicate dependencies.');
+        }
+        if (trait[$internal].relation || isRelation(trait)) {
+            throw new Error('Koota: Relations cannot be predicate dependencies.');
+        }
+    }
+    return Object.assign(createModifier('predicate', ++predicateId, traits), { predicate }) as PredicateModifier<T>;
+}
+
+export function evaluatePredicate(world: World, entity: Entity, modifier: Modifier): boolean {
+    const predicate = modifier.predicate!;
+    for (const trait of modifier.traits) if (!hasTrait(world, entity, trait)) return false;
+    return predicate(modifier.traits.map((trait) => getTrait(world, entity, trait)));
+}
+
+/** Re-check only queries whose predicate depends on a changed trait. */
+export function checkPredicateQueries(world: World, entity: Entity, trait: Trait): void {
+    const data = world[$internal].traitInstances[trait.id];
+    if (!data) return;
+    for (const query of data.predicateQueries) {
+        query.toRemove.remove(entity);
+        const match = query.relationFilters?.length
+            ? checkQueryWithRelations(world, query, entity)
+            : query.check(world, entity);
+        if (match) query.add(entity);
+        else query.remove(world, entity);
+    }
+}
