+import { Added, Changed, createAdded, createChanged, createPredicate, createRemoved, createWorld, Not, Or, relation, Removed, trait } from '../src';
+
+describe('value predicates', () => {
+    const Score = trait({ value: 0 });
+    const Level = trait({ value: 0 });
+
+    it('filters by dependency values and does not add callback data', () => {
+        const HighScore = createPredicate([Score, Level], ([score, level]) => score.value >= level.value);
+        const world = createWorld();
+        const high = world.spawn(Score({ value: 4 }), Level({ value: 2 }));
+        const low = world.spawn(Score({ value: 1 }), Level({ value: 2 }));
+        expect(world.query(HighScore)).toEqual([high]);
+        world.set(low, Score, { value: 3 });
+        expect(world.query(HighScore)).toEqual([high, low]);
+        world.query(Score, HighScore).readEach(([score]) => expect(score.value).toBeGreaterThan(0));
+    });
+
+    it('supports Not, Or, and predicate transition tracking', () => {
+        const HighScore = createPredicate([Score], ([score]) => score.value > 1);
+        const Added = createAdded();
+        const Removed = createRemoved();
+        const Changed = createChanged();
+        const world = createWorld();
+        const entity = world.spawn(Score({ value: 0 }));
+        expect(world.query(Not(HighScore))).toEqual([entity]);
+        expect(world.query(Or(HighScore))).toEqual([]);
+        world.set(entity, Score, { value: 2 });
+        expect(world.query(Added(HighScore))).toEqual([entity]);
+        expect(world.query(Changed(HighScore))).toEqual([entity]);
+        world.set(entity, Score, { value: 0 });
+        expect(world.query(Removed(HighScore))).toEqual([entity]);
+        expect(world.query(Changed(HighScore))).toEqual([entity]);
+    });
+
+    it('rejects tags and relations as dependencies', () => {
+        const Tag = trait();
+        const Parent = relation();
+        expect(() => createPredicate([Tag], () => true)).toThrow();
+        expect(() => createPredicate([Parent as any], () => true)).toThrow();
+    });
+});
